// ========================================
// n8n CODE NODE — Outlook Kalender
// Version: 18.06.2026 — ISO-Datum Architektur
// + Datums-Validierung (03.07.2026)
// + Multi-Tenant tenantId (09.08.2026)
// Erwartet Input: "YYYY-MM-DD [uhrzeit] Uhr [titel]"
//           oder: "YYYY-MM-DD ganztägig [titel]"
// Datum kommt fertig vom Intent Layer (Code Node 2)
// ========================================
// ---------- INPUT ----------
const raw =
  $json.body?.message || $json.body?.text ||
  $json.message || $json.text || "";
const input = String(raw).trim();
if (!input) throw new Error("Kein Input gefunden");
const text = input.toLowerCase();
// ---------- DATUM (ISO) ----------
const isoMatch = text.match(/(\d{4})-(\d{2})-(\d{2})/);
if (!isoMatch) throw new Error("Kein Datum erkannt");
const year  = parseInt(isoMatch[1], 10);
const month = parseInt(isoMatch[2], 10) - 1;
const day   = parseInt(isoMatch[3], 10);

// ---------- DATUMS-VALIDIERUNG (NEU 03.07.2026) ----------
// Verhindert dass JS Date() ungültige Werte (z.B. Monat 13, Tag 45)
// stillschweigend in ein falsches, aber valides Datum umrechnet.
if (month < 0 || month > 11) {
  throw new Error(`Ungültiges Datum erkannt: Monat ${month + 1} existiert nicht`);
}
if (day < 1 || day > 31) {
  throw new Error(`Ungültiges Datum erkannt: Tag ${day} existiert nicht`);
}
const daysInMonth = new Date(year, month + 1, 0).getDate();
if (day > daysInMonth) {
  throw new Error(`Ungültiges Datum erkannt: ${day}.${month + 1}.${year} existiert nicht (Monat hat nur ${daysInMonth} Tage)`);
}

// Arbeitskopie ohne ISO-Datum — verhindert dass Datum
// fälschlich als Uhrzeit interpretiert wird
const textNoDate = text.replace(/\d{4}-\d{2}-\d{2}/, " ").trim();
// ---------- GANZTÄGIG ----------
const allDayKeyword = /ganztägig|ganztags|ganzer tag|ganzen tag/i.test(textNoDate);
const hasTime = /(\d{1,2})[:.](\d{2})/.test(textNoDate) || /(\d{1,2})\s*uhr/i.test(textNoDate);
const isAllDay = allDayKeyword || !hasTime;
// ---------- ZEIT ----------
let hour = 10, minute = 0;
if (!isAllDay) {
  const fullTime = textNoDate.match(/(\d{1,2})[:.](\d{2})/);
  if (fullTime) {
    hour = parseInt(fullTime[1], 10);
    minute = parseInt(fullTime[2], 10);
  } else {
    const hourOnly = textNoDate.match(/(\d{1,2})\s*uhr/);
    if (hourOnly) hour = parseInt(hourOnly[1], 10);
  }
}

// ---------- ZEIT-VALIDIERUNG (NEU 03.07.2026) ----------
if (hour < 0 || hour > 23) {
  throw new Error(`Ungültige Uhrzeit erkannt: ${hour} Uhr existiert nicht`);
}
if (minute < 0 || minute > 59) {
  throw new Error(`Ungültige Uhrzeit erkannt: ${minute} Minuten existiert nicht`);
}

// ---------- DAUER ----------
let durationHours = 1, durationDays = 1;
const hourMatch = textNoDate.match(/f[uü]r\s+(\d+)\s*stund/i);
if (hourMatch) durationHours = parseInt(hourMatch[1], 10);
const dayMatch = textNoDate.match(/f[uü]r\s+(\d+)\s*tag/i);
if (dayMatch) durationDays = parseInt(dayMatch[1], 10);
// ---------- START / ENDE ----------
let startDate = new Date(year, month, day);
let endDate;
if (isAllDay) {
  startDate.setHours(0, 0, 0, 0);
  endDate = new Date(startDate);
  endDate.setDate(startDate.getDate() + durationDays);
} else {
  startDate.setHours(hour, minute, 0, 0);
  endDate = new Date(startDate);
  endDate.setHours(endDate.getHours() + durationHours);
}
// ---------- FORMAT ----------
function formatDate(date) {
  const pad = (n) => String(n).padStart(2, "0");
  return `${date.getFullYear()}-${pad(date.getMonth()+1)}-${pad(date.getDate())} `
       + `${pad(date.getHours())}:${pad(date.getMinutes())}:00`;
}
const formatAllDay = (date) =>
  `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}T00:00:00`;
// ---------- TITEL ----------
let title = input;
title = title
  .replace(/\d{4}-\d{2}-\d{2}/g, "")
  .replace(/\d{1,2}([:.]\d{2})?\s*uhr/gi, "")
  .replace(/^(erstelle\s+(einen?\s+)?termin\s*)/i, "")
  .replace(/f[uü]r\s+\d+\s*stunden?/gi, "")
  .replace(/f[uü]r\s+\d+\s*tagen?/gi, "")
  .replace(/\b(ganztägig|ganztags|ganzer tag|ganzen tag)\b/gi, "")
  .replace(/^(neuer\s+termin\s*)/i, "")
  .replace(/^(buche\s+(einen?\s+)?termin\s*)/i, "")
  .replace(/\btermin\b/gi, "")
  .replace(/\s+/g, " ").trim();
if (!title) title = "Termin";
// ---------- OUTPUT ----------
return [{
  json: {
    title,
    start: isAllDay ? formatAllDay(startDate) : formatDate(startDate),
    end:   isAllDay ? formatAllDay(endDate)   : formatDate(endDate),
    isAllDay,
    timezone: isAllDay ? "" : "Europe/Berlin",
    originalInput: input,
    tenantId: $json.body?.tenantId || 'default'
  }
}];

