// Termin kategorisieren (Keyword-Match)
// Mode: Run Once for Each Item -- Return: einzelnes Objekt, KEIN Array!

const DEFAULT_KATEGORIEN = [
  { name: "Kundentermin", keywords: ["kunde", "meeting", "besprechung", "call"] },
  { name: "Akquise", keywords: ["akquise", "erstgespr\u00e4ch", "pitch", "neukunde"] },
  { name: "Angebot", keywords: ["angebot", "beratung", "kalkulation"] },
  { name: "Vertragsabschluss", keywords: ["vertrag", "abschluss", "unterzeichnung"] },
  { name: "Internes", keywords: ["intern", "team", "planung"] },
  { name: "Sonstiges", keywords: [] }
];

// jonas_profile.value ist immer TEXT -- json_object_agg liefert die gespeicherte
// JSON-Liste als STRING zurueck, nicht als geparstes Array (gleiches Muster wie
// abend_recap_asked_items). Muss explizit geparst werden, sonst 'kategorien.map
// is not a function' (Live-Incident 05.09.2026, Execution 140553).
const profile = $json.profile || {};
let kategorien = DEFAULT_KATEGORIEN;
if (profile.kalender_kategorien) {
  try {
    const parsed = JSON.parse(profile.kalender_kategorien);
    if (Array.isArray(parsed) && parsed.length) kategorien = parsed;
  } catch (e) { /* Parse-Fehler -> DEFAULT_KATEGORIEN bleibt stehen */ }
}

const title = $('Datum & Zeit parsen').first().json.title || "";
const titleLower = title.toLowerCase();

let matchedName = null;
for (const kat of kategorien) {
  const keywords = kat.keywords || [];
  if (keywords.some((kw) => titleLower.includes(String(kw).toLowerCase()))) {
    matchedName = kat.name;
    break;
  }
}

return {
  json: {
    category: matchedName,
    categoryFound: matchedName !== null,
    source: "keyword",
    kategorienNamen: kategorien.map((k) => k.name),
    title
  }
};

// Kategorie-Prompt bauen (LLM-Fallback)
// Mode: Run Once for Each Item -- Return: einzelnes Objekt, KEIN Array!

const kategorienNamen = $json.kategorienNamen && $json.kategorienNamen.length
  ? $json.kategorienNamen
  : ["Kundentermin", "Akquise", "Angebot", "Vertragsabschluss", "Internes", "Sonstiges"];
const title = $json.title || "";

const systemPrompt = "Du kategorisierst Kalendertermine f\u00fcr ein Business. Antworte AUSSCHLIESSLICH mit einem JSON-Objekt der Form {\"category\": \"<Name>\"}. W\u00e4hle den Namen exakt aus dieser Liste: " + kategorienNamen.join(", ") + ". Wenn nichts passt, w\u00e4hle \"Sonstiges\".";
const userMessage = "Termintitel: \"" + title + "\"";

return {
  json: {
    systemPrompt,
    userMessage,
    kategorienNamen
  }
};

// Kategorie-Antwort parsen
// Mode: Run Once for Each Item -- Return: einzelnes Objekt, KEIN Array!

const raw = $json.text || '';
const kategorienNamen = $('Kategorie-Prompt bauen').first().json.kategorienNamen || [];
let category = 'Sonstiges';
try {
  const start = raw.indexOf('{');
  const end = raw.lastIndexOf('}');
  const parsed = JSON.parse(raw.slice(start, end + 1));
  if (parsed.category && kategorienNamen.includes(parsed.category)) {
    category = parsed.category;
  }
} catch (e) { }

return { json: { category, source: "llm" } };
